func:
// Parse si string
var d = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload;

// Validation des plages physiques
if (d.temp < -10 || d.temp > 60) { node.warn('Temp aberrante: ' + d.temp); return null; }
if (d.hum < 0 || d.hum > 100) { node.warn('Hum aberrante: ' + d.hum); return null; }
if (d.co2 && (d.co2 < 300 || d.co2 > 5000)) { node.warn('CO2 aberrant: ' + d.co2); return null; }

// Format influxdb-out v2
msg.payload = [{
    temp: d.temp,
    hum:  d.hum,
    co2:  d.co2  || 0,
    lux:  d.lux  || 0,
    pres: d.pres || 0,
    rssi: d.rssi || 0
}];
msg.payload[0].tags = { node_id: d.id };
msg.measurement = 'environment';

// Passer les donnees brutes pour l automatisation
msg._raw = d;
return msg;

var d       = msg._raw;
var co2     = d.co2  || 0;
var pres    = d.pres || 0;
var lux     = d.lux  || 0;
var node_id = d.id;

var cmds = [];

// --- SCENARIO 2 : Qualite d air ---
if (co2 > 1500) {
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'relay2', val:'ON'}) });
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'buzzer', val:'ON'}) });
    node.warn('ALERTE CRITIQUE CO2=' + co2 + ' ppm sur ' + node_id);
} else if (co2 > 1000) {
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'relay2', val:'ON'}) });
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'buzzer', val:'OFF'}) });
} else {
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'relay2', val:'OFF'}) });
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'buzzer', val:'OFF'}) });
}

// --- SCENARIO 1 : Eclairage adaptatif ---
if (pres === 1 && lux < 200) {
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'relay1', val:'ON'}) });
} else if (pres === 0) {
    cmds.push({ topic: 'smartroom/cmds/' + node_id, payload: JSON.stringify({act:'relay1', val:'OFF'}) });
}

// Retourner chaque commande comme message separe
return [ cmds ];
